const SUPPORTED_EXTENSIONS=new Set(['pdf','docx','pptx','xlsx','epub','txt','md','markdown','html','htm','png','jpg','jpeg','webp']);
const PODCAST_LANGUAGE_KEY='sread_podcast_language_v1';

function artifactStatusText(item:Artifact){
  const quality=item.payload?.quality_control;if(quality)return `${quality.score==null?'暂未评分':`${quality.score} 分`}/${quality.target_score} 目标 · ${quality.phase!=='complete'?'自动处理中':quality.met_target?'达到本档生成目标':'已保留内容'}`;
  const delivery:Record<string,string>={full:'已生成',partial:'部分生成',script_only:'仅脚本',draft_only:'仅草稿'};
  if(item.payload?.delivery_status){const review=item.payload?.quality_assessment;return `${delivery[item.payload.delivery_status]||item.status} · ${review?`核对 ${review.reviewed_units}/${review.total_units} 项`:'无核查记录'}`}
  const report=item.payload?.quality_report;
  if(item.status==='partial'||report?.partial){
    const generated=Number(report?.generated_count??item.payload?.turns?.length??0);
    const requested=Number(report?.requested_count??report?.target_turn_count??0);
    return requested>0?`部分完成 · ${generated}/${requested}`:'部分完成';
  }
  return ({ready:'已就绪',partial:'部分完成',failed:'失败',generating:'生成中'} as Record<string,string>)[item.status]||'已保存';
}

type QualityIssue={unit?:string;code:string;message:string;severity?:string};
function QualityRating({value,status}:{value?:{level:string;reviewed_units:number;total_units:number;supported_units?:number;reason?:string;review_status?:string;issues:QualityIssue[]};status?:string}){
  const delivery:Record<string,string>={full:'已生成',partial:'部分生成',script_only:'仅脚本',draft_only:'仅草稿'};
  const title=!value?'历史内容 · 无核查记录':value.review_status==='not_applicable'?'原文核查不适用':value.reviewed_units>0?`已核对 ${value.reviewed_units}/${value.total_units} 项`:`尚未完成原文核查（0/${value.total_units}）`;
  return <details className="generation-warnings"><summary>{status?`${delivery[status]||status} · `:''}{title}</summary><p>{value?`获得有效原文核查结论 ${value.reviewed_units||0} / ${value.total_units||0} 项${value.supported_units!==undefined?`，其中原文支持 ${value.supported_units} 项`:''}。结构可用与事实支持分别判断。`:'旧产物没有记录，不能推断当时是否完成核查。'}</p>{value?.reason?<p>{value.reason}</p>:value&&value.reviewed_units<value.total_units?<p>未记录完整原因；可能只完成了抽样核查。未检查不算通过，也不代表内容有误。</p>:null}{value?.issues?.map((issue,index)=><p key={index}>{issue.unit?`${issue.unit}：`:''}{issue.message}</p>)}<small>自动检查不保证事实正确。重要结论请点击引用核对原文。</small></details>
}

function PodcastCoherence({audit}:{audit?:import('./api').EpisodeAudit}){
  return <div className="generation-warnings" role="status" aria-label="播客连贯性检查"><b>{audit?.status==='complete'?'连贯性检查已完成':audit?.status==='partial'?'连贯性已部分检查':'连贯性未验证'}</b><p>{audit?.status?`已检查 ${audit.checked_transitions} / ${audit.total_transitions} 处相邻对话；自动检查不保证语义完整。`:'此产物没有完整的连贯性检查记录。'}{audit?.reason?` ${audit.reason}`:''}{audit?.repair_unreviewed?' 局部修复文字未经独立复核。':''}</p>{audit?.transition_checks?.filter(check=>check.verdict!=='connected').map(check=><p key={check.index}>第 {check.index+1}–{check.index+2} 轮：{check.reason}</p>)}</div>;
}

function ItemQuality({issues}:{issues?:QualityIssue[]}){return issues?.length?<details className="study-feedback"><summary>核查备注</summary>{issues.map((issue,index)=><p key={index}>待核实：{issue.message}</p>)}</details>:null}

function GenerationWarnings({warnings}:{warnings?:{code:string;stage:string;message:string}[]}){
  if(!warnings?.length)return null;
  return <div className="generation-warnings" role="status" aria-label="生成结果说明"><b>部分要求未达到</b><ul>{warnings.map((warning,index)=><li key={`${warning.code}-${index}`}>{warning.message}</li>)}</ul></div>;
}

type Coverage={preparation?:{planned_batches?:number;attempted_batches?:number;failed_batches?:number;accepted_notes?:number};stages?:Record<string,{sent_segments:number;source_tokens:number}>;audit?:{supported:number;unsupported:number;unreviewed:number};candidate_segments:number;selected_segments:number;sent_segments:number;partially_sent_segments:number;cited_segments?:number;sources?:Array<{source_id:string;filename:string;regions_total:number;regions_sent:number;unsent_regions:string[]}>;plan:{total_token_limit:number;evidence_tokens:number;limiting_factor:string}};
function CoverageDetails({coverage}:{coverage?:Coverage}){
  if(!coverage)return null;
  return <details className="coverage-details"><summary>本次资料覆盖 · 实际送入 {coverage.sent_segments} 段</summary><p>候选 {coverage.candidate_segments} 段 · 选材 {coverage.selected_segments} 段 · 成功调用完整送入 {coverage.sent_segments} 段 · 部分送入 {coverage.partially_sent_segments} 段{coverage.cited_segments!==undefined?` · 最终引用 ${coverage.cited_segments} 段`:''}</p><p>MAIN 总预算上限 {coverage.plan.total_token_limit.toLocaleString()} tokens · {coverage.plan.limiting_factor}</p>{coverage.stages?<p>预读 {coverage.stages.context_prepare?.sent_segments||0} 段 · {coverage.stages.act_draft||coverage.stages.targeted_repair?<>章节写作 {coverage.stages.act_draft?.sent_segments??0} 段 · 技术恢复 {coverage.stages.targeted_repair?.sent_segments??0} 段</>:<>最终生成 {coverage.stages.summary?.sent_segments??coverage.stages.generation?.sent_segments??0} 段</>}（阶段间可重复）</p>:null}{coverage.preparation?.attempted_batches!==undefined?<p>预读完成 {Math.max(0,(coverage.preparation.attempted_batches||0)-(coverage.preparation.failed_batches||0))} / {coverage.preparation.planned_batches||0} 批 · 保留 {coverage.preparation.accepted_notes||0} 条带原文定位的笔记</p>:null}{coverage.audit?.supported!==undefined?<p>模型核验支持 {coverage.audit.supported} 项 · 不支持 {coverage.audit.unsupported} 项 · 未完成 {coverage.audit.unreviewed} 项</p>:null}{coverage.sources?.map(source=><details key={source.source_id}><summary>{source.filename} · 涉及 {source.regions_sent}/{source.regions_total} 个内容区间</summary><p>{source.unsent_regions.length?`未完整送入：${source.unsent_regions.join('、')}`:'各区间均有原文片段送入；不表示逐字读完。'}</p></details>)}<small>统计原文片段的使用情况，不代表重要信息完整覆盖或质量验收通过。</small></details>;
}

export function Logo(){return <div className="brand"><div className="mark"><Zap size={20}/></div><div><strong>SANDEVISTAN</strong><span>// READ</span></div></div>}

export function LoginScreen({onLogin,error}:{onLogin:(key:string)=>Promise<void>;error:string}){
  const[value,setValue]=useState('');const[busy,setBusy]=useState(false);
  async function submit(){if(!value||busy)return;setBusy(true);try{await onLogin(value)}catch{/* Parent supplies the inline error. */}finally{setBusy(false)}}
  return <main className="login-screen"><form className="login-box" onSubmit={event=>{event.preventDefault();void submit()}}>
    <Logo/><span>SECURE PERIMETER // LAN MODE</span><h1>访问授权</h1>
    <p>服务正在局域网接口监听。请输入项目配置中的访问密钥以建立会话。</p>
    <label>访问密钥<input type="password" autoFocus autoComplete="current-password" placeholder="ACCESS KEY" value={value} onChange={event=>setValue(event.target.value)}/></label>
    <button disabled={!value||busy} type="submit">{busy?'正在验证…':'授权访问'} <Zap size={15}/></button>
    {error?<em role="alert">{error}</em>:null}<small>密钥位于本机项目的 runtime/config.toml，不会发送给其它服务。</small>
  </form></main>;
}

export function Header({notebook,notebooks,status,onSelect,onCreate,onSettings,route}:{notebook?:Notebook;notebooks:Notebook[];status:any;onSelect:(id:string)=>void;onCreate:(title:string)=>Promise<void>;onSettings:()=>void;route:string}){
  const[open,setOpen]=useState(false);const[title,setTitle]=useState('');const[creating,setCreating]=useState(false);const menuRef=useRef<HTMLDivElement>(null);
  useEffect(()=>setOpen(false),[route]);
  useEffect(()=>{
    if(!open)return;
    const outside=(event:PointerEvent)=>{if(!menuRef.current?.contains(event.target as Node))setOpen(false)};
    const escape=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)};
    document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);
    return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape)};
  },[open]);
  async function create(){const next=title.trim();if(!next||creating)return;setCreating(true);try{await onCreate(next);setTitle('');setOpen(false)}catch{/* Keep the draft open. */}finally{setCreating(false)}}
  return <header>
    <button className="brand-link" onClick={()=>{location.hash='workspace'}} aria-label="返回工作台"><Logo/></button>
    <nav className="top-nav" aria-label="主导航">
      <button aria-current={route==='workspace'?'page':undefined} className={route==='workspace'?'active':''} onClick={()=>{location.hash='workspace'}}><Zap size={16}/><span>工作台</span></button>
      <button aria-current={route==='jobs'?'page':undefined} className={route==='jobs'?'active':''} onClick={()=>{location.hash='jobs'}}><ClipboardList size={16}/><span>任务</span></button>
      <button aria-current={route==='notebooks'?'page':undefined} className={route==='notebooks'?'active':''} onClick={()=>{location.hash='notebooks'}}><Library size={16}/><span>资料库</span></button>
    </nav>
    <div className="notebook-menu" ref={menuRef}>
      <button className="notebook-switch" aria-expanded={open} aria-controls="notebook-popover" onClick={()=>setOpen(value=>!value)}><span>当前资料库</span><b>{notebook?.title||'选择或新建资料库'}</b><ChevronDown size={15}/></button>
      {open?<div className="notebook-popover" id="notebook-popover" role="dialog" aria-label="选择 Notebook">
        <div className="notebook-options">{notebooks.map(item=><button key={item.id} className={item.id===notebook?.id?'active':''} onClick={()=>{onSelect(item.id);location.hash='workspace';setOpen(false)}}>{item.title}</button>)}</div>
        <form className="notebook-create" onSubmit={event=>{event.preventDefault();void create()}}><label className="sr-only" htmlFor="quick-notebook-title">新资料库名称</label><input id="quick-notebook-title" value={title} onChange={event=>setTitle(event.target.value)} placeholder="新资料库名称"/><button aria-label="创建资料库" disabled={!title.trim()||creating} type="submit"><Plus size={15}/></button></form>
      </div>:null}
    </div>
    <div className="header-actions"><div className={`connection ${status?.providers?.main?.ok?'online':status?'':'pending'}`}><Wifi size={15}/><span>{status?.providers?.main?.ok?'文字模型可用':status?'文字模型待连接':'正在连接'}</span></div><button className="icon-button" onClick={onSettings} aria-label="设置"><Settings2 size={19}/></button></div>
  </header>;
}

export function SourceRail({sources,hasNotebook,imagePolicy,providers,onUpload,onToggle,onDelete,onNotify}:{sources:Source[];hasNotebook:boolean;imagePolicy:ImageProcessingPolicy;providers:Provider[];onUpload:(files:File[],policy:ImageProcessingPolicy)=>Promise<void>;onToggle:(source:Source)=>Promise<void>;onDelete:(source:Source)=>Promise<void>;onNotify:(message:string,tone?:'info'|'success'|'error')=>void}){
  const[override,setOverride]=useState(false);const[query,setQuery]=useState('');const[dragging,setDragging]=useState(false);const[uploading,setUploading]=useState(false);const[working,setWorking]=useState('');const[deleting,setDeleting]=useState<Source>();const[pending,setPending]=useState<File[]>();const[uploadPolicy,setUploadPolicy]=useState<ImageProcessingPolicy>(imagePolicy);const input=useRef<HTMLInputElement>(null);
  const visible=useMemo(()=>sources.filter(source=>source.filename.toLowerCase().includes(query.toLowerCase())),[sources,query]);
  const selected=sources.filter(source=>source.selected&&source.state==='ready').length;
  async function accept(files:FileList|File[]){
    if(!hasNotebook){onNotify('请先新建或选择一个 Notebook','error');return}
    const all=Array.from(files);const supported=all.filter(file=>SUPPORTED_EXTENSIONS.has(file.name.split('.').pop()?.toLowerCase()||''));
    if(supported.length!==all.length)onNotify('已忽略不支持的文件格式','error');if(!supported.length)return;
    setUploadPolicy({mode:imagePolicy.mode,processors:[...imagePolicy.processors]});setOverride(false);setPending(supported);
  }
  async function confirmUpload(){if(!pending)return;setUploading(true);try{await onUpload(pending,uploadPolicy);setPending(undefined);if(input.current)input.current.value=''}catch{/* Parent shows the error. */}finally{setUploading(false)}}
  function toggleProcessor(processor:'vlm'|'main'|'ocr'){setUploadPolicy(current=>{const exists=current.processors.includes(processor);const processors=exists?current.processors.filter(item=>item!==processor):[...current.processors,processor];return{mode:processors.length?'process':'off',processors}})}
  async function toggle(source:Source){setWorking(source.id);try{await onToggle(source)}catch{/* Parent shows the error. */}finally{setWorking('')}}
  return <aside className="sources panel" aria-label="资料">
    <div className="panel-title"><span>资料 SOURCES</span><em>{selected}/{sources.length}</em></div>
    <label className={`upload-zone ${dragging?'drag-active':''} ${sources.length?'has-sources':''} ${!hasNotebook?'disabled':''}`} onDragEnter={event=>{event.preventDefault();if(hasNotebook)setDragging(true)}} onDragOver={event=>event.preventDefault()} onDragLeave={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node))setDragging(false)}} onDrop={event=>{event.preventDefault();setDragging(false);void accept(event.dataTransfer.files)}}>
      <input ref={input} type="file" multiple disabled={!hasNotebook||uploading} accept=".pdf,.docx,.pptx,.xlsx,.epub,.txt,.md,.markdown,.html,.htm,.png,.jpg,.jpeg,.webp" onChange={event=>event.target.files&&void accept(event.target.files)}/><Upload/><b>{uploading?'正在接入资料…':dragging?'松开以上传':'拖放或点击上传'}</b><small>PDF · EPUB · DOCX/PPTX/XLSX · WEB · 图片</small>
    </label>
    <label className="source-tools"><Search size={15}/><span className="sr-only">搜索资料</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="搜索资料"/></label>
    <div className="source-list">{visible.length===0?<div className="empty"><FileText/><p>{sources.length?'没有匹配资料':hasNotebook?'等待资料接入':'请先选择资料库'}</p></div>:null}{visible.map(source=><div key={source.id} className={`source-row ${source.selected?'selected':''}`}>
      <button className="source" aria-pressed={Boolean(source.selected)} disabled={working===source.id||source.state!=='ready'} onClick={()=>void toggle(source)}><span className="check">{source.selected?<Check size={13}/>:null}</span><span><b title={source.filename}>{source.filename}</b><small className={source.state==='failed'?'failed':''}>{source.state==='ready'?`${source.page_count||1} ${source.metadata?.locator_unit==='sheet'?'张工作表':source.metadata?.locator_unit==='slide'?'张幻灯片':source.metadata?.locator_unit==='chapter'?'章':'页'} · 已索引`:source.state==='failed'?source.error||'解析失败':({queued:'等待解析',processing:'正在解析',parsing:'正在解析',indexing:'正在索引'} as Record<string,string>)[source.state]||'正在处理'}</small>{Array.isArray(source.metadata?.warnings)&&source.metadata.warnings.length?<small className="warning">{source.metadata.warnings.map((warning:{message?:string})=>warning.message).filter(Boolean).join(' ')}</small>:null}</span></button>
      <details className="source-info"><summary>资料详情</summary><p>{source.filename}</p>{source.error?<p className="source-error">{source.error}</p>:null}</details>
      <button className="source-delete" aria-label={`删除 ${source.filename}`} onClick={()=>setDeleting(source)}><Trash2 size={15}/></button>
    </div>)}</div>
    <button className="add-source" disabled={!hasNotebook||uploading} onClick={()=>input.current?.click()}><Plus size={15}/> 添加资料</button>
    {pending?<Overlay className="upload-confirm" layer="nested" label="确认上传" onClose={()=>setPending(undefined)} variant="dialog" eyebrow={<>INGEST POLICY // NEW FILES</>} title={<>确认接入 {pending.length} 份资料</>} footer={<div className="provider-form-actions"><button onClick={()=>setPending(undefined)}>取消</button><button className="primary" disabled={uploading||uploadPolicy.mode==='process'&&!uploadPolicy.processors.length} onClick={()=>void confirmUpload()}>{uploading?'正在上传…':'确认上传'}</button></div>}><p>已继承默认图片处理方式，无需再次勾选。只影响新上传的资料。模型识图会额外消耗 token，可在解析任务详情查看；本地 OCR 不调用模型。</p><p>{uploadPolicy.mode==='off'?'默认不处理图片':uploadPolicy.processors.map(item=>item.toUpperCase()).join(' → ')}</p>{uploadPolicy.mode==='process'?<ul>{uploadPolicy.processors.map(item=><li key={item}>{item.toUpperCase()}：{imageProcessorState(item,providers)}</li>)}</ul>:null}<button onClick={()=>setOverride(value=>!value)} aria-expanded={override}>仅修改本次</button>{override?<div><label className="provider-check"><input type="checkbox" checked={uploadPolicy.mode==='process'} onChange={event=>setUploadPolicy(current=>({mode:event.target.checked?'process':'off',processors:event.target.checked&&!current.processors.length?['vlm','main','ocr']:current.processors}))}/> 处理资料中的图片</label>{uploadPolicy.mode==='process'?<div className="upload-processors">{(['vlm','main','ocr'] as const).map(processor=><label key={processor}><input type="checkbox" checked={uploadPolicy.processors.includes(processor)} onChange={()=>toggleProcessor(processor)}/><b>{processor.toUpperCase()}</b><small>{processor==='vlm'?'专用视觉模型':processor==='main'?'主模型视觉能力':'本地文字识别'}</small></label>)}</div>:<p className="capability-note">图片会保留，但不会调用模型或 OCR；纯图片资料将没有可检索文本。</p>}</div>:null}<small>执行顺序：{uploadPolicy.mode==='off'?'关闭':uploadPolicy.processors.map(item=>item.toUpperCase()).join(' → ')||'请选择至少一步'}；成功后停止。</small></Overlay>:null}
    {deleting?<ConfirmDialog key={deleting.id} title={`删除资料“${deleting.filename}”`} description="将删除该资料的本地文件和索引，Notebook 中其它内容不受影响。" confirmLabel="删除资料" onCancel={()=>setDeleting(undefined)} onConfirm={async()=>{await onDelete(deleting);setDeleting(undefined)}}/>:null}
  </aside>;
}

export function ChatPanel({tools,guide,showOnboarding=false,setupRequired=false,notebookId,sourceIds,tokenLimit,onTokenLimit,messages,question,setQuestion,onAsk,busy,loading=false,onCitation,onNewConversation,onOpenStudio,hasNotebook,selectedCount}:{tools?:ReactNode;guide?:ReactNode;showOnboarding?:boolean;setupRequired?:boolean;messages:any[];question:string;setQuestion:(value:string)=>void;onAsk:()=>Promise<void>;busy:boolean;loading?:boolean;onCitation:(citation:Citation)=>void;onNewConversation:()=>void;onOpenStudio:()=>void;hasNotebook:boolean;selectedCount:number;notebookId?:string;sourceIds:string[];tokenLimit?:number;onTokenLimit:(value:number|undefined)=>void}){
  const[guideOpen,setGuideOpen]=useState(false);const[showLatest,setShowLatest]=useState(false);
  const[toolsOpen,setToolsOpen]=useState(false);
  const messageList=useRef<HTMLDivElement>(null);const following=useRef(true);const prior=useRef({notebookId,first:'',count:0});
  const hideComposer=showOnboarding&&setupRequired&&!loading;
  const messageRevision=messages.map(message=>`${message.id}:${message.content}:${JSON.stringify(message.metadata?.quality_control||{})}`).join('|');
  function scrollLatest(){const element=messageList.current;if(element){element.scrollTop=element.scrollHeight;following.current=true;setShowLatest(false)}}
  useLayoutEffect(()=>{
    const first=messages[0]?.id||'',last=messages.at(-1);
    const changed=prior.current.notebookId!==notebookId||prior.current.first!==first;
    const sent=messages.length>prior.current.count&&last?.role==='user';
    if(changed||following.current||sent)scrollLatest();else setShowLatest(true);
    prior.current={notebookId,first,count:messages.length};
  },[notebookId,messageRevision,busy]);
  useEffect(()=>{
    const element=messageList.current;if(!element)return;
    const observer=new ResizeObserver(()=>{if(following.current)scrollLatest()});
    observer.observe(element);element.querySelectorAll('.message').forEach(message=>observer.observe(message));
    return()=>observer.disconnect();
  },[notebookId,messages.length]);
  const disabledReason=loading?'正在加载对话…':!hasNotebook?'请先选择或新建资料库':selectedCount===0?'请先选择至少一份资料':'';
  return <main className={`chat panel ${hideComposer?'chat-onboarding':''}`}><div className="chat-heading"><div><span>GROUNDING CONSOLE</span><h1><button className="chat-title-menu" onClick={()=>setToolsOpen(true)} aria-label="历史对话与资料范围">向资料提问 ▾</button></h1></div><div className="chat-actions"><button className="guide-trigger" onClick={()=>setGuideOpen(true)}>使用指南</button><button className="tablet-studio-trigger" onClick={onOpenStudio}><PanelRightOpen/> Studio</button><button aria-label="新对话" onClick={onNewConversation} disabled={loading||!messages.length}>新对话</button><div className="strict"><span/> 严格溯源</div></div></div>
    {toolsOpen?<Overlay label="对话与资料" title={<>对话与资料</>} onClose={()=>setToolsOpen(false)}>{tools}</Overlay>:null}<div className="messages" ref={messageList} onScroll={()=>{const element=messageList.current;if(element){following.current=element.scrollHeight-element.clientHeight-element.scrollTop<96;if(following.current)setShowLatest(false)}}} role="log" aria-live="polite">{showOnboarding&&!loading&&guide?guide:messages.length===0?<div className="welcome"><div className="scan-icon"><BrainCircuit/></div><span>{hasNotebook?'NEURAL LINK READY':'SELECT A NOTEBOOK'}</span><h2>{hasNotebook?'从资料中，得到可验证的答案。':'先创建一个资料库，开始阅读。'}</h2><p>{hasNotebook?'回答仅依据当前勾选的文档。生成内容会尽量附带可追溯引用，点击即可核对原文位置。':'你可以在顶部切换 Notebook，或前往资料库管理页新建资料库。'}</p>{hasNotebook?<div className="prompts"><button disabled={!selectedCount} onClick={()=>setQuestion('这些资料最重要的三个结论是什么？')}>提炼三个核心结论</button><button disabled={!selectedCount} onClick={()=>setQuestion('资料之间有哪些观点冲突？')}>查找观点冲突</button></div>:<button className="primary welcome-action" onClick={()=>{location.hash='notebooks'}}>管理资料库</button>}</div>:messages.map((message,index)=><article key={message.id||index} className={`message ${message.role}`}><label>{message.role==='user'?'你的问题':'S-READ · GROUNDED'}</label><div className="message-body"><RichText content={String(message.content||'')} citations={message.citations||[]} onCitation={onCitation}/></div>{message.role==='assistant'?<><CopyResult content={String(message.content||'')} citations={message.citations||[]}/><QualityResult value={message.metadata?.quality_control} targetType="message"/><details className="result-details"><summary>查看详情</summary>{message.metadata?.quality_control?<QualityEvidence value={message.metadata.quality_control}/>:<QualityRating value={message.quality_assessment||message.metadata?.quality_assessment} status={message.delivery_status||message.metadata?.delivery_status}/>}<UsageDetails value={message.metadata?.usage} legacy={message.metadata?.context_usage}/><GenerationWarnings warnings={message.warnings||message.metadata?.warnings}/><CoverageDetails coverage={message.metadata?.context_usage?.coverage}/></details></>:null}<CitationIndex citations={message.citations||[]} onCitation={onCitation}/></article>)}{busy?<div className="thinking" role="status"><i/><i/><i/> 正在比对资料并核验引用</div>:null}</div>
    {showLatest?<button className="latest-message" onClick={scrollLatest}>回到最新 ↓</button>:null}{!hideComposer?<div className="composer"><label className="sr-only" htmlFor="grounded-question">向已选资料提问</label><textarea id="grounded-question" value={question} disabled={loading||!hasNotebook||busy} onChange={event=>setQuestion(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.nativeEvent.isComposing&&event.nativeEvent.keyCode!==229){event.preventDefault();void onAsk()}}} placeholder={disabledReason||'向当前选中的资料提问…'}/><QualitySelector kind="chat"/><TaskEstimate presentation="responsive-dialog" notebookId={notebookId} kind="chat" sourceIds={sourceIds} question={question} limit={tokenLimit} onLimit={onTokenLimit}/><button onClick={()=>void onAsk()} disabled={busy||!question.trim()||Boolean(disabledReason)||!validTokenLimit(tokenLimit)}>{busy?'核验中…':'发送'} <Zap size={15}/></button><div className="composer-meta"><span><BookOpen size={14}/> {selectedCount?`已选择 ${selectedCount} 份资料`:'仅检索已选择资料'} · Enter 发送</span></div></div>:null}{guideOpen?<Overlay label="使用指南" className="guide-dialog" onClose={()=>setGuideOpen(false)}>{isValidElement<{onNavigate?:()=>void}>(guide)?cloneElement(guide,{onNavigate:()=>setGuideOpen(false)}):guide}</Overlay>:null}
  </main>;
}

const cards=[['summary','资料摘要',Sparkles,'凝练核心结论与限制'],['podcasts','双人播客',Headphones,'两位主持人深入解读'],['quiz','测验题库',Check,'生成可验证的单选题'],['flashcards','闪卡复习',Layers3,'用闪卡巩固关键知识']] as const;
function etaText(job:Job){if(job.eta?.status==='learning')return `ETA 学习中 · ${job.eta.sample_count}/5 样本`;const range=job.eta?.remaining_range||[];return range.length===2?`ETA ${Math.ceil(range[0]/60)}–${Math.ceil(range[1]/60)} 分钟`:'ETA 计算中'}
export function StudioRail({reminders,notebookId,onCreate,onOpen,onConfigureAudio,artifacts,jobs,hasNotebook,selectedCount,podcastUnavailableReason}:{reminders?:ReactNode;onCreate:(type:string)=>Promise<void>;onOpen:(artifact:Artifact)=>void;onConfigureAudio:()=>void;artifacts:Artifact[];jobs:Job[];hasNotebook:boolean;selectedCount:number;podcastUnavailableReason:string;notebookId?:string}){
  const[allOpen,setAllOpen]=useState(false);const[query,setQuery]=useState('');const[type,setType]=useState('all');
  useEffect(()=>{setAllOpen(false);setQuery('');setType('all')},[notebookId]);
  const filtered=useMemo(()=>artifacts.filter(item=>(type==='all'||item.type===type)&&item.title.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())),[artifacts,query,type]);
  const active=jobs.filter(job=>['running','queued','cancelling'].includes(job.state)).slice(0,3);const failed=jobs.filter(job=>job.state==='failed').slice(0,2);const disabled=!hasNotebook||selectedCount===0;const podcastRequirementId=useId();
  return <aside className="studio panel" aria-label="Studio"><div className="panel-title"><span>学习与输出</span><em>已选 {selectedCount} 份</em></div><p className="studio-intro">将已选资料转化为可学习内容。</p>{disabled?<p className="studio-hint">{hasNotebook?'选择至少一份已索引资料后即可生成。':'先选择或新建资料库。'}</p>:null}<div className="studio-cards">{cards.map(([type,title,Icon,description])=>{const podcastScriptOnly=type==='podcasts'&&Boolean(podcastUnavailableReason);return <button key={type} disabled={disabled} aria-describedby={podcastScriptOnly?podcastRequirementId:undefined} title={podcastScriptOnly?`${podcastUnavailableReason} · 仍可生成对话脚本`:undefined} onClick={()=>void onCreate(type)}><Icon/><span><b>{title}</b><small>{description}</small></span><Plus size={15}/></button>})}</div>
    {podcastUnavailableReason?<details className="studio-provider-hint" id={podcastRequirementId} ><summary>播客语音（可选）</summary><span><b>音频服务离线 · 双人播客将仅生成文本</b><small>{podcastUnavailableReason}</small></span>{podcastUnavailableReason==='正在检查 AUDIO Provider…'?null:<button type="button" onClick={onConfigureAudio}>配置 AUDIO Provider</button>}</details>:null}
    {reminders}<NotebookUsage id={notebookId}/><div className="activity"><div className="panel-title"><span>输出记录</span><button className="inline-link" onClick={()=>setAllOpen(true)}>全部成果（{artifacts.length}）</button><button className="inline-link" onClick={()=>{location.hash='jobs'}}>全部任务</button></div>{active.map(job=><button className="job job-button" key={job.id} onClick={()=>{location.hash='jobs'}}><span>{job.display_name||job.kind.toUpperCase()} · {Math.round(job.progress*100)}%</span><small>{job.stage}{job.stage_total?` · ${job.stage_current}/${job.stage_total}${job.stage_unit||''}`:''}</small><i><b style={{width:`${job.progress*100}%`}}/></i><small>{job.state==='queued'&&job.eta?.queue_position?`队列第 ${job.eta.queue_position} 位 · `:''}{etaText(job)}</small></button>)}{failed.map(job=><button className="job job-button failed-job" key={job.id} onClick={()=>{location.hash='jobs'}}><span>{job.kind.toUpperCase()} · FAILED</span><small>{job.error}</small></button>)}{artifacts.slice(0,6).map(item=><button className="artifact" key={item.id} onClick={()=>onOpen(item)}><FileText size={16}/><span><b>{item.title}</b><small>{({summary:'摘要',podcast:'播客',quiz:'测验',flashcard:'闪卡'})[item.type]} · {artifactStatusText(item)}</small></span></button>)}{!artifacts.length&&!active.length?<p className="no-output">尚无生成内容</p>:null}</div>
    {allOpen?<Overlay label="全部成果" className="output-library" onClose={()=>setAllOpen(false)}><div className="output-filters"><label>搜索成果<input value={query} onChange={event=>setQuery(event.target.value)} placeholder="按名称搜索"/></label><label>成果类型<select value={type} onChange={event=>setType(event.target.value)}><option value="all">全部类型</option><option value="summary">摘要</option><option value="podcast">播客</option><option value="quiz">测验</option><option value="flashcard">闪卡</option></select></label></div><p role="status">共 {filtered.length} 份成果</p><div className="output-list">{filtered.map(item=><button className="artifact" key={item.id} onClick={()=>onOpen(item)}><FileText size={18}/><span><b>{item.title}</b><small>{({summary:'摘要',podcast:'播客',quiz:'测验',flashcard:'闪卡'})[item.type]} · {artifactStatusText(item)}</small></span><span>打开</span></button>)}</div>{!filtered.length?<p className="empty">{artifacts.length?'没有匹配的成果，请调整搜索条件。':'生成的摘要、播客、测验和闪卡会显示在这里。'}</p>:null}</Overlay>:null}
  </aside>;
}

export function CitationDrawer({citation,onClose}:{citation:Citation|null;onClose:()=>void}){
  if(!citation)return null;
  const visualId=citation.locator?.visual_id;
  return <Overlay className="citation-drawer" layer="nested" label={`引用 ${citation.id}`} onClose={onClose} eyebrow={<>SOURCE TRACE // {citation.id}</>} title={<>{citation.filename}</>}>{visualId?<><em className="visual-citation-label">派生视觉证据 · 可核对原图</em><img className="citation-visual" src={`/api/visuals/${encodeURIComponent(String(visualId))}/image`} alt={`${citation.filename} 中的引用图片`}/></>:null}<div className="locator">{Object.entries(citation.locator||{}).filter(([key])=>!['visual_id','derived_visual'].includes(key)).map(([key,value])=><i key={key}>{({page:'页码',slide:'幻灯片',sheet:'工作表',chapter:'章节',paragraph:'段落',row:'行',section:'小节'} as Record<string,string>)[key]||key}: {String(value)}</i>)}</div><blockquote>{citation.quote}</blockquote>{citation.revision_id?<a href={`/api/sources/${encodeURIComponent(citation.source_id)}/file?revision=${encodeURIComponent(citation.revision_id)}${citation.locator?.page?`#page=${citation.locator.page}`:''}`} target="_blank" rel="noreferrer">{citation.filename.toLowerCase().endsWith('.pdf')?'打开原文页':'打开或下载原始资料'}</a>:<p>历史引用未记录原始修订，保留摘录供核对。</p>}<small>{visualId?'文字为图片处理链产生的派生描述；原图来自固定修订版本。':'该片段来自上传资料的固定修订版本。'}</small></Overlay>;
}

function initialPodcastLanguage(){try{return (localStorage.getItem(PODCAST_LANGUAGE_KEY) as 'zh-CN'|'auto'|'en')||'zh-CN'}catch{return 'zh-CN' as const}}
export function PodcastCreateModal({rangePicker,notebookId,sourceIds,provider,unavailableReason,sourceCount,onClose,onCreate}:{rangePicker?:ReactNode;provider?:Provider;unavailableReason?:string;sourceCount:number;notebookId?:string;sourceIds:string[];onClose:()=>void;onCreate:(options:PodcastOptions)=>Promise<void>}){
  const[tokenLimit,setTokenLimit]=useState<number>();
  const[duration,setDuration]=useState<'auto'|'5'|'10'|'20'|'30'>('auto');const[language,setLanguage]=useState<'zh-CN'|'auto'|'en'>(initialPodcastLanguage);const[focus,setFocus]=useState('');const[busy,setBusy]=useState(false);
  const device=String(provider?.config?.compute_device||'未配置').toUpperCase(),model=provider?.model||'未配置',asrDevice=String(provider?.config?.asr_compute_device||'未配置').toUpperCase(),asrModel=provider?.config?.asr_model||'未配置',audioRange=duration==='auto'?'12–25':duration;
  async function submit(){if(busy)return;setBusy(true);try{try{localStorage.setItem(PODCAST_LANGUAGE_KEY,language)}catch{/* Optional preference. */}await onCreate({token_limit:tokenLimit,duration_mode:duration==='auto'?'auto':'fixed',minutes:duration==='auto'?undefined:Number(duration) as 5|10|20|30,language,focus})}catch{/* Keep the form open. */}finally{setBusy(false)}}
  return <Overlay className="podcast-create" label="生成双人深度播客" onClose={onClose} closeOnBackdrop={false} variant="dialog" eyebrow={<>PODCAST V4 // EDITORIAL ACTS</>} title={<>生成双人深度播客</>} footer={<button className="primary" disabled={busy||!validTokenLimit(tokenLimit)} onClick={()=>void submit()}>{busy?'正在提交…':unavailableReason?'仅生成对话脚本':'生成深度播客'}</button>}>{unavailableReason?<p className="podcast-degraded-hint" role="status">当前无法合成音频：{unavailableReason}。仍可生成双人对话脚本；配置 AUDIO Provider 后可产出完整播客。</p>:null}<details className="generation-service-details"><summary>语音配置详情</summary><div className="podcast-provider"><b>TTS · {model}</b><small>{device} · {sourceCount} SOURCES · 严格资料内</small><b>ASR · {asrModel}</b><small>{asrDevice} · 双说话人验收</small></div></details><label>目标时长<select value={duration} onChange={event=>setDuration(event.target.value as typeof duration)}><option value="auto">AUTO · 12–25 分钟</option><option value="5">5 分钟 · QUICK</option><option value="10">10 分钟 · STANDARD</option><option value="20">20 分钟 · DEEP</option><option value="30">30 分钟 · EXTENDED</option></select></label><label>输出语言<select value={language} onChange={event=>setLanguage(event.target.value as typeof language)}><option value="zh-CN">简体中文</option><option value="auto">跟随资料</option><option value="en">English</option></select></label><label>关注重点<textarea value={focus} onChange={event=>setFocus(event.target.value)} maxLength={1000} placeholder="可选：希望两位主持人重点讨论什么？"/></label><div className="podcast-estimate"><span>预计成片</span><b>{audioRange} MIN</b><span>预计生成</span><b>提交后按本地历史预测</b></div><p>少量长 Act 完成整集编排和审校，成品再由本地 ASR 验收；可用产物会保留；时长或质量未达标时，会标明具体差异。</p>{rangePicker}<QualitySelector kind="podcast"/><TaskEstimate notebookId={notebookId} kind="podcast" sourceIds={sourceIds} minutes={duration==='auto'?20:Number(duration)} limit={tokenLimit} onLimit={setTokenLimit}/></Overlay>;
}

export function StudyCreateModal({rangePicker,notebookId,sourceIds,kind,provider,sourceCount,onClose,onCreate}:{rangePicker?:ReactNode;kind:'quiz'|'flashcard';notebookId?:string;sourceIds:string[];provider?:Provider;sourceCount:number;onClose:()=>void;onCreate:(options:StudyOptions)=>Promise<void>}){
  const[tokenLimit,setTokenLimit]=useState<number>();
  const defaults=kind==='quiz'?{few:5,standard:10,more:20}:{few:10,standard:20,more:40};
  const[amount,setAmount]=useState<keyof typeof defaults>('standard');const[difficulty,setDifficulty]=useState<StudyOptions['difficulty']>('mixed');const[language,setLanguage]=useState<StudyOptions['language']>('auto');const[customPrompt,setCustomPrompt]=useState('');const[busy,setBusy]=useState(false);
  const profile=provider?.capabilities?.study_generation,tier=profile?.tier||'lite';
  async function submit(){if(busy||!provider)return;setBusy(true);try{await onCreate({token_limit:tokenLimit,count:defaults[amount],difficulty,language,custom_prompt:customPrompt.trim()})}catch{/* Keep options available after an API error. */}finally{setBusy(false)}}
  const title=kind==='quiz'?'生成理解型 Quiz':'生成可复习 Flashcards';
  return <Overlay className="study-create" label={title} onClose={onClose} closeOnBackdrop={false} variant="dialog" eyebrow={<>STUDY PIPELINE // {tier.toUpperCase()}</>} title={<>{title}</>} footer={<button className="primary" disabled={busy||!provider||!validTokenLimit(tokenLimit)} onClick={()=>void submit()}>{busy?'正在提交…':`生成 ${kind==='quiz'?'Quiz':'闪卡复习'}`}</button>}><div className={`study-tier study-tier-${tier}`}><b>{provider?.model||'未配置 MAIN Provider'}</b><small>{tier==='full'?'分批生成 · 一次原文抽查':'小批次生成 · 一次原文抽查'} · {sourceCount} SOURCES</small>{profile?.reason?<em>{profile.reason}</em>:null}</div>
    <label>数量<select value={amount} onChange={event=>setAmount(event.target.value as keyof typeof defaults)}><option value="few">较少 · {defaults.few}</option><option value="standard">标准 · {defaults.standard}</option><option value="more">较多 · {defaults.more}</option></select></label>
    <label>难度<select value={difficulty} onChange={event=>setDifficulty(event.target.value as StudyOptions['difficulty'])}><option value="mixed">混合</option><option value="easy">简单</option><option value="medium">中等</option><option value="hard">困难</option></select></label>
    <label>输出语言<select value={language} onChange={event=>setLanguage(event.target.value as StudyOptions['language'])}><option value="auto">跟随资料</option><option value="zh-CN">简体中文</option><option value="en">English</option></select></label>
    <label>定制要求<textarea value={customPrompt} onChange={event=>setCustomPrompt(event.target.value)} maxLength={1000} placeholder="可选：指定考试范围、受众、侧重点或题目风格。"/></label>
    <p>按所选难度生成并校验证据；数量或难度未达到时，会保留可用题卡并标明差异。</p>
    {rangePicker}<QualitySelector kind={kind}/><TaskEstimate notebookId={notebookId} kind={kind} sourceIds={sourceIds} count={defaults[amount]} limit={tokenLimit} onLimit={setTokenLimit}/>
  </Overlay>;
}

function pendingIndex(session:StudySession){const index=session.items.findIndex(item=>session.kind==='quiz'?!item.result:!item.review);return index<0?Math.max(0,session.items.length-1):index}

function StudyArtifactDrawer({artifact,onClose,onCitation}:{artifact:Artifact;onClose:()=>void;onCitation:(citation:Citation)=>void}){
  const[notice,setNotice]=useState('');const[paused,setPaused]=useState<string>();const[session,setSession]=useState<StudySession>();const[index,setIndex]=useState(0);const[selection,setSelection]=useState<Record<string,number>>({});const[flipped,setFlipped]=useState(false);const[hint,setHint]=useState(false);const[explain,setExplain]=useState(false);const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[fullscreen,setFullscreen]=useState(false);
  useEffect(()=>{let active=true;setSession(undefined);setError('');void createStudySession(artifact.id,artifact.type==='quiz'?'all':'due').then(value=>{if(active){setSession(value);setIndex(pendingIndex(value))}}).catch(reason=>{if(active)setError(reason instanceof Error?reason.message:'无法开始学习会话')});return()=>{active=false}},[artifact.id,artifact.type]);
  const item=session?.items[index];
  async function restart(mode:'all'|'missed'|'due'|'same',shuffle=false){setBusy(true);setError('');try{const value=await createStudySession(artifact.id,mode,shuffle);setSession(value);setIndex(pendingIndex(value));setFlipped(false);setHint(false);setExplain(false)}catch(reason){setError(reason instanceof Error?reason.message:'无法创建学习会话')}finally{setBusy(false)}}
  async function checkAnswer(){if(!session||!item||selection[item.id]===undefined||item.result||busy)return;setBusy(true);try{const response=await answerQuizItem(session.id,item.id,selection[item.id]);setSession(response.session)}catch(reason){setError(reason instanceof Error?reason.message:'答案提交失败')}finally{setBusy(false)}}
  async function rate(rating:'again'|'hard'|'good'|'easy'){if(!session||!item||busy)return;setBusy(true);try{const response=await reviewStudyCard(session.id,item.id,rating);setNotice(response.due_at?`下次复习：${new Date(response.due_at).toLocaleString()}`:'复习记录已保存');window.dispatchEvent(new Event('sread-study-changed'));const value=response.session as StudySession;setSession(value);setIndex(pendingIndex(value));setFlipped(false);setExplain(false)}catch(reason){setError(reason instanceof Error?reason.message:'复习记录保存失败')}finally{setBusy(false)}}
  async function removeCard(){if(!session||!item||busy)return;setBusy(true);try{await suspendFlashcard(artifact.id,item.id);setPaused(item.id);setNotice('已暂停复习，记忆状态和历史记录保留。');window.dispatchEvent(new Event('sread-study-changed'));const value=await getStudySession(session.id);setSession(value);setIndex(pendingIndex(value));setFlipped(false);setHint(false);setExplain(false)}catch(reason){setError(reason instanceof Error?reason.message:'闪卡移除失败')}finally{setBusy(false)}}
  const completed=session?.status==='complete',quizCorrect=session?.items.filter(value=>value.result?.correct).length||0;
  return <Overlay className={`artifact-drawer study-drawer ${fullscreen?'study-fullscreen':''}`} label={artifact.title} onClose={onClose} eyebrow={<>ACTIVE STUDY // {artifact.type.toUpperCase()}</>} title={<>{artifact.title}</>}><div className="study-head"><div><b>{session?.progress.current||0} / {session?.progress.total||0}</b><small>{({due:'到期复习',all:'全部内容',missed:'错题重练',same:'继续本轮'} as Record<string,string>)[session?.mode||'']||'载入中'} · {artifact.payload?.quality_report?.pipeline_tier==='full'?'完整题组':'学习进度'}</small></div><button aria-label="切换全屏" onClick={()=>setFullscreen(value=>!value)}><Maximize2/></button></div>{session?<i className="study-progress"><b style={{width:`${session.progress.total?session.progress.current/session.progress.total*100:0}%`}}/></i>:null}{!artifact.payload?.quality_control&&(artifact.status==='partial'||artifact.payload?.quality_report?.partial)?<em className="degraded">仅保留 {artifact.payload?.quality_report?.generated_count} 个可用内容</em>:null}<QualityResult value={artifact.payload?.quality_control} targetType="artifact"/><details className="result-details"><summary>查看详情</summary>{artifact.payload?.quality_control?<QualityEvidence value={artifact.payload.quality_control}/>:<QualityRating value={artifact.payload?.quality_assessment} status={artifact.payload?.delivery_status}/>}<UsageDetails value={artifact.payload?.usage} legacy={artifact.payload?.context_usage}/><GenerationWarnings warnings={artifact.payload?.warnings}/><CoverageDetails coverage={artifact.payload?.context_usage?.coverage}/></details>{error?<p className="study-error" role="alert">{error}</p>:null}
    {notice?<p role="status">{notice}</p>:null}{paused?<button disabled={busy} onClick={()=>{setBusy(true);void restoreFlashcard(artifact.id,paused,session?.id).then(response=>{if(response.session){setSession(response.session);setIndex(Math.max(0,response.session.items.findIndex(card=>card.id===paused)))}setPaused(undefined);setNotice('已恢复复习');window.dispatchEvent(new Event('sread-study-changed'))}).catch(e=>setError(e.message)).finally(()=>setBusy(false))}}>撤销暂停</button>:null}
    {!session&&!error?<p className="study-empty">正在恢复学习进度…</p>:null}
    {session&&!item?<div className="study-empty"><BrainCircuit/><h3>当前队列没有待学习内容</h3><p>可以重新学习全部内容，或稍后回来到期复习。</p><button className="primary" onClick={()=>void restart('all')}>学习全部</button></div>:null}
    {session&&item&&session.kind==='quiz'?<div className="quiz-study"><nav className="quiz-number-nav" aria-label="题目导航">{session.items.map((question,number)=><button key={question.id} aria-current={number===index?'step':undefined} onClick={()=>{setIndex(number);setHint(false)}}>{number+1} · {question.result?question.result.correct?'正确':'待复习':'未答'}</button>)}<button disabled={!session.items.some(q=>!q.result)} onClick={()=>{setIndex(pendingIndex(session));setHint(false)}}>跳到未答题</button></nav><div className="question-nav"><button disabled={index===0} onClick={()=>{setIndex(value=>value-1);setHint(false)}}><ChevronLeft/>上一题</button><span>{index+1} / {session.items.length}</span><button disabled={index===session.items.length-1} onClick={()=>{setIndex(value=>value+1);setHint(false)}}>下一题<ChevronRight/></button></div><small className="learning-objective">{({easy:'基础',medium:'中等',hard:'进阶'} as Record<string,string>)[item.difficulty||'']} · {({remember:'记忆',understand:'理解',apply:'应用',analyze:'分析',evaluate:'评价'} as Record<string,string>)[item.cognitive_level||'']||''} · {item.learning_objective}</small><h3>{item.question}</h3><div className="quiz-options">{item.options?.map((option:string,optionIndex:number)=>{const result=item.result;const state=result?optionIndex===result.answer_index?'correct':optionIndex===result.selected_index?'wrong':'':selection[item.id]===optionIndex?'selected':'';return <button className={state} disabled={Boolean(result)} key={optionIndex} onClick={()=>setSelection(value=>({...value,[item.id]:optionIndex}))}><b>{String.fromCharCode(65+optionIndex)}</b><span>{option}</span></button>})}</div><div className="quiz-actions"><button onClick={()=>setHint(value=>!value)}><Lightbulb/>提示</button><button className="primary" disabled={selection[item.id]===undefined||Boolean(item.result)||busy} onClick={()=>void checkAnswer()}>{busy?'核验中…':'检查答案'}</button></div>{hint&&!item.result?<p className="study-feedback hint"><Lightbulb/> {item.hint||'回到资料中的核心概念与关系进行判断。'}</p>:null}{item.result?<div className={`study-feedback ${item.result.correct?'feedback-correct':'feedback-wrong'}`}><b>{item.result.correct?'回答正确':'需要再看一遍'}</b><p>{item.result.explanation}</p><button disabled={index===session.items.length-1} onClick={()=>{setIndex(value=>value+1);setHint(false)}}>阅读解析后，下一题</button><ItemQuality issues={item.result.quality_issues}/><div className="item-citations">{item.result.citation_details?.map((citation:Citation)=><button key={citation.id} onClick={()=>onCitation(citation)}>[{citation.id}] {citation.filename}</button>)}</div></div>:null}</div>:null}
    {session&&item&&session.kind==='flashcard'?<div className="flash-study"><div className="flash-tools"><button onClick={()=>void restart('same',true)} disabled={busy}><Shuffle/>洗牌</button><a href={flashcardsCsvUrl(artifact.id)} download><Download/>CSV</a><button className="danger-action" onClick={()=>void removeCard()} disabled={busy}><Trash2/>暂停复习</button></div><button className={`flash-card ${flipped?'flipped':''}`} onClick={()=>setFlipped(value=>!value)}><small>{item.difficulty?.toUpperCase()} · {item.card_type?.toUpperCase()}</small><span>{flipped?item.back:item.front}</span><em>{flipped?'背面 · 点击翻回':'正面 · 回忆后翻面'}</em></button>{flipped?<><ItemQuality issues={item.quality_issues}/><button className="explain-toggle" onClick={()=>setExplain(value=>!value)}><BrainCircuit/>解释</button>{explain?<div className="study-feedback"><p>{item.explanation||'该答案由下列资料片段支持。'}</p><div className="item-citations">{item.citation_details?.map((citation:Citation)=><button key={citation.id} onClick={()=>onCitation(citation)}>[{citation.id}] {citation.filename}</button>)}</div></div>:null}<p>再来：尚未记住；困难：费力想起；良好：正常回忆；简单：轻松掌握。根据真实回忆情况选择。</p><div className="ratings ratings-four">{([['again','再来'],['hard','困难'],['good','良好'],['easy','简单']] as const).map(([rating,label])=><button disabled={busy} key={rating} onClick={()=>void rate(rating)}>{label}</button>)}</div></>:null}</div>:null}
    {completed&&session.items.length?<div className="study-complete"><Check/><h3>{session.kind==='quiz'?`完成 · ${quizCorrect}/${session.items.length}`:'本轮复习完成'}</h3><p>{session.kind==='quiz'?'可以只重做错题，或重新挑战全部题目。':'FSRS 已根据反馈安排下次复习。'}</p><div>{session.kind==='quiz'?<button onClick={()=>void restart('missed')}>只练错题</button>:<button onClick={()=>void restart('missed')}>只练再来卡</button>}<button onClick={()=>void restart('same')}><RotateCcw/>相同内容</button><button className="primary" onClick={()=>void restart('all')}>全部重练</button></div></div>:null}
  </Overlay>;
}

export function ArtifactDrawer({artifact:originalArtifact,onClose,onCitation}:{artifact:Artifact|null;onClose:()=>void;onCitation:(citation:Citation)=>void;onSubmitQuiz:(id:string,answers:Record<string,number>)=>Promise<any>;onReview:(id:string,cardId:string,rating:string)=>Promise<void>}){
  const[audioVersion,setAudioVersion]=useState<Artifact>();const artifact=audioVersion||originalArtifact;
  const[currentTime,setCurrentTime]=useState(0);const[audioError,setAudioError]=useState('');const audioRef=useRef<HTMLAudioElement>(null);
  const citationById=useMemo(()=>new Map((artifact?.citations||[]).map(citation=>[citation.id,citation])),[artifact]);
  if(!artifact)return null;
  if(artifact.type==='quiz'||artifact.type==='flashcard')return <StudyArtifactDrawer artifact={artifact} onClose={onClose} onCitation={onCitation}/>;
  const turns=Array.isArray(artifact.payload?.turns)?artifact.payload.turns:[],chapters=Array.isArray(artifact.payload?.chapters)?artifact.payload.chapters:[],activeTurn=turns.findIndex((turn:any)=>currentTime>=Number(turn.start_seconds||0)&&currentTime<(Number(turn.end_seconds||0)));
  function seek(seconds:number){if(audioRef.current){audioRef.current.currentTime=seconds;void audioRef.current.play().catch(()=>setAudioError('播放失败，请重试或下载音频。'))}}
  return <Overlay className="artifact-drawer" label={artifact.title} onClose={onClose} eyebrow={<>STUDIO OUTPUT // {artifact.type.toUpperCase()}</>} title={<>{artifact.title}</>}>{artifact.type==='podcast'&&!artifact.payload?.quality_control?<><PodcastCoherence audit={artifact.payload?.quality_report?.episode_audit}/>{artifact.payload?.generation_mode&&artifact.payload.generation_mode!=='legacy'?<p className="context-adjusted" role="status">{artifact.payload.generation_mode==='expanded'?'展开版':'完整短版'} · {artifact.payload.narrative_status==='complete'?'收尾检查通过':artifact.payload.narrative_status==='incomplete'?'完整性不足，仅草稿':'收尾待核实'}<small> 结构完整不代表事实检查全部通过。</small></p>:null}</>:null}{artifact.payload?.degraded&&!artifact.payload?.quality_control?<em className="degraded">已保留可用内容 · 部分要求未达到</em>:null}<QualityResult value={artifact.payload?.quality_control} targetType="artifact"/><details className="result-details"><summary>查看详情</summary>{artifact.payload?.quality_control?<QualityEvidence value={artifact.payload.quality_control}/>:<QualityRating value={artifact.payload?.quality_assessment} status={artifact.payload?.delivery_status}/>}<UsageDetails value={artifact.payload?.usage} legacy={artifact.payload?.context_usage}/><GenerationWarnings warnings={artifact.payload?.warnings}/><CoverageDetails coverage={artifact.payload?.context_usage?.coverage}/>{artifact.type==='podcast'?<>{artifact.payload?.fact_review?<p className="context-adjusted" role="status">原文核验 {artifact.payload.fact_review.reviewed}/{artifact.payload.fact_review.total} 项 · 支持 {artifact.payload.fact_review.supported} · 矛盾疑点 {artifact.payload.fact_review.contradicted} · 待核实 {artifact.payload.fact_review.uncertain}<small> 未核验部分不算通过；点击对话引用可查看原文。</small></p>:null}{artifact.payload?.source_contributions?.some(source=>!source.included)?<p className="context-adjusted">本集未涵盖 {artifact.payload.source_contributions.filter(source=>!source.included).length} 份已选资料；已选材不等于已讲解。</p>:null}<div className="podcast-meta"><span>TARGET <b>{artifact.payload?.duration?.target_minutes} MIN</b></span><span>ACTUAL <b>{Math.round(Number(artifact.payload?.duration?.actual_seconds||0)/60)} MIN</b></span><span>时长 <b>{artifact.payload?.audio_quality?.duration?.passed===true?'达到参考范围':artifact.payload?.audio_quality?.duration?.passed===false?'偏离目标，仅作提示':'未测量'}</b></span><span>TTS <b>{artifact.payload?.provider?.model}</b></span><span>SCRIPT <b>V{artifact.payload?.version}{artifact.payload?.quality?.passed===true?' · PASSED':''}</b></span><span>AUDIO <b>{artifact.payload?.audio_quality?.passed===true?'VERIFIED':'UNVERIFIED'}</b></span><span>TTS DEVICE <b>{String(artifact.payload?.provider?.compute_device||'').toUpperCase()}{artifact.payload?.provider?.fallback_used?' · CPU FALLBACK':''}</b></span><span>ASR <b>{artifact.payload?.provider?.asr?.model||artifact.payload?.audio_quality?.asr_model||'LEGACY'}</b></span><span>ASR DEVICE <b>{String(artifact.payload?.provider?.asr?.compute_device||artifact.payload?.audio_quality?.compute_device||'').toUpperCase()}{(artifact.payload?.provider?.asr?.fallback_used||artifact.payload?.audio_quality?.device_fallback)?' · CPU FALLBACK':''}</b></span>{artifact.payload?.audio_quality?.error_rate!=null?<span>{String(artifact.payload.audio_quality.metric||'ERROR').toUpperCase()} <b>{(Number(artifact.payload.audio_quality.error_rate)*100).toFixed(1)}%</b></span>:null}{artifact.payload?.audio_quality?.speaker_alignment!=null?<span>说话人对齐 <b>{(Number(artifact.payload.audio_quality.speaker_alignment)*100).toFixed(1)}%</b></span>:null}{artifact.payload?.audio_quality?.silence_outliers!=null?<span>异常静音 <b>{artifact.payload.audio_quality.silence_outliers}</b></span>:null}{artifact.payload?.audio_quality?.speaker_method?<span>对齐评估 <b>{artifact.payload.audio_quality.speaker_method==='word_speaker'?'逐词说话人':artifact.payload.audio_quality.speaker_method==='segment_overlap'?'分段估计':'混合／不可用'}</b></span>:null}{artifact.payload?.audio_quality?.speaker_coverage!=null?<span>对齐覆盖 <b>{(artifact.payload.audio_quality.speaker_coverage*100).toFixed(1)}%</b></span>:null}</div></>:null}</details>{artifact.payload?.context_usage?.adjusted?<em className="context-adjusted">已按模型窗口调整证据量</em>:null}
    {artifact.type==='summary'?<div className="artifact-copy"><CopyResult content={String(artifact.payload?.content||'')} citations={artifact.citations}/><a href={`/api/artifacts/${artifact.id}/summary.md`} download>导出 Markdown</a><RichText content={String(artifact.payload?.content||'')} citations={artifact.citations} onCitation={onCitation}/></div>:null}
    {artifact.type==='podcast'?<div className="podcast-view">{audioVersion?.id!==originalArtifact?.id&&audioVersion?<QualityResult value={originalArtifact?.payload?.quality_control} targetType="artifact"/>:null}<AudioRenderVersions original={originalArtifact!} selected={artifact.id} onSelect={value=>{audioRef.current?.pause();setAudioVersion(value);setCurrentTime(0);setAudioError('')}}/><div className="podcast-downloads"><a href={podcastDownloadUrl(artifact.id)} download><Download size={15}/>打包下载</a>{artifact.media_url?<a href={podcastDownloadUrl(artifact.id,'audio')} download>音频</a>:null}<a href={podcastDownloadUrl(artifact.id,'script','markdown')} download>脚本 MD</a><a href={podcastDownloadUrl(artifact.id,'script','json')} download>脚本 JSON</a></div>{artifact.media_url?<audio key={artifact.id} onError={()=>setAudioError('音频加载失败，请重试或下载文件。')} ref={audioRef} controls preload="metadata" src={artifact.media_url} onTimeUpdate={event=>setCurrentTime(event.currentTarget.currentTime)}/>:<p>当前仅保留脚本，暂无可播放音频。</p>}{audioError?<p role="alert">{audioError}<button onClick={()=>{setAudioError('');audioRef.current?.load()}}>重试加载</button></p>:null}{Number(artifact.payload?.version)>=2?<><nav className="podcast-chapters" aria-label="播客章节">{chapters.map((chapter:any)=><button key={chapter.id} onClick={()=>{if(artifact.media_url)seek(Number(chapter.start_seconds||0));else document.getElementById(`turn-${turns.find((turn:any)=>turn.chapter_id===chapter.id)?.id||turns[Number(chapter.turn_start)||0]?.id}`)?.scrollIntoView({block:'center'})}}>{chapter.title}</button>)}</nav><div className="podcast-transcript">{turns.map((turn:any,turnIndex:number)=><div id={`turn-${turn.id}`} role={artifact.media_url?'button':undefined} tabIndex={artifact.media_url?0:undefined} key={turn.id} className={`podcast-turn ${turnIndex===activeTurn?'active':''}`} onClick={()=>seek(Number(turn.start_seconds||0))} onKeyDown={event=>{if(artifact.media_url&&(event.key==='Enter'||event.key===' ')){event.preventDefault();seek(Number(turn.start_seconds||0))}}}><b>{turn.speaker==='HOST_A'?'A':'B'}</b><span>{turn.text}<ItemQuality issues={turn.quality_issues}/><small>{turn.citation_ids?.map((citationId:string)=>{const citation=citationById.get(citationId);return citation?<button key={citationId} onClick={event=>{event.stopPropagation();onCitation(citation)}}>[{citationId}]</button>:null})}</small></span></div>)}</div></>:<div className="artifact-copy"><RichText content={String(artifact.payload?.script||'')} citations={artifact.citations} onCitation={onCitation}/></div>}</div>:null}
    <CitationIndex citations={artifact.citations||[]} onCitation={onCitation}/>
  </Overlay>;
}

export function SummaryCreateModal({rangePicker,notebookId,sourceIds,onClose,onCreate}:{rangePicker?:ReactNode;notebookId:string;sourceIds:string[];onClose:()=>void;onCreate:(options:import('./api').SummaryOptions)=>Promise<void>}){
  const[limit,setLimit]=useState<number>();const[busy,setBusy]=useState(false);const[focus,setFocus]=useState('');const[length,setLength]=useState<import('./api').SummaryOptions['length']>('standard');const[language,setLanguage]=useState('auto');
  return <Overlay label="生成资料摘要" className="study-create" onClose={onClose} closeOnBackdrop={false} variant="dialog" title={<>生成资料摘要</>} footer={<button className="primary" disabled={busy||!validTokenLimit(limit)} onClick={()=>{setBusy(true);void onCreate({token_limit:limit,focus,length,language}).catch(()=>{}).finally(()=>setBusy(false))}}>{busy?'正在提交…':'生成摘要'}</button>}><p>提炼结论与限制，保留各资料的原文引用；首版生成后即可阅读，系统按所选质量自动评分和改进。</p><label>侧重点（可选）<textarea maxLength={1000} value={focus} onChange={e=>setFocus(e.target.value)}/></label><label>篇幅<select value={length} onChange={e=>setLength(e.target.value as typeof length)}><option value="brief">简短</option><option value="standard">标准</option><option value="detailed">详细</option></select></label><label>输出语言<select value={language} onChange={e=>setLanguage(e.target.value)}><option value="auto">跟随资料</option><option value="zh-CN">简体中文</option><option value="en">English</option></select></label>{rangePicker}<QualitySelector kind="summary"/><TaskEstimate notebookId={notebookId} kind="summary" sourceIds={sourceIds} limit={limit} onLimit={setLimit}/></Overlay>
}


export function ChatResultDrawer({conversationId,messageId,onClose,onCitation,onContinue}:{conversationId:string;messageId:string;onClose:()=>void;onCitation:(citation:Citation)=>void;onContinue:()=>void}){
  const[message,setMessage]=useState<any>(),[error,setError]=useState('');
  useEffect(()=>{let stopped=false,inFlight=false,timer:number|undefined;const refresh=async()=>{if(inFlight)return;inFlight=true;try{const rows=await getMessages(conversationId);if(stopped)return;const next=rows.find(item=>item.id===messageId);setMessage(next);setError(next?'':'该结果已不存在');if(next&&['queued','generating','scoring','improving','rendering'].includes(next.metadata?.quality_control?.phase)){if(timer)clearTimeout(timer);timer=window.setTimeout(()=>void refresh(),2000)}}catch{if(!stopped)setError('暂时无法读取结果，请关闭后重试')}finally{inFlight=false}};void refresh();window.addEventListener('sread-quality-changed',refresh);return()=>{stopped=true;if(timer)clearTimeout(timer);window.removeEventListener('sread-quality-changed',refresh)}},[conversationId,messageId]);
  return <Overlay className="artifact-drawer" label="对话结果" onClose={onClose} title={<>对话结果</>}><button onClick={onContinue}>进入对话继续提问</button>{error?<p role="alert">{error}</p>:message?<><RichText content={message.content||''} citations={message.citations||[]} onCitation={onCitation}/><QualityResult value={message.metadata?.quality_control} targetType="message"/><details className="result-details"><summary>查看详情</summary><QualityEvidence value={message.metadata?.quality_control}/><UsageDetails value={message.metadata?.usage}/></details><CitationIndex citations={message.citations||[]} onCitation={onCitation}/></>:<p>正在读取…</p>}</Overlay>
}
